recipes.code:
{
  "inputs": [
    {
      "id": "instavar-api-key",
      "type": "promptString",
      "description": "Per-user API key from https://instavar.com/studio/settings. Scoped to your org and revocable.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@instavar/mcp-server@0.3.0"
      ],
      "env": {
        "INSTAVAR_API_KEY": "${input:instavar-api-key}",
        "INSTAVAR_BASE_URL": "https://instavar.com"
      }
    }
  }
}
